const items = $input.all();
return items.map(item => {
  const html = item.json.data || item.json.body || '';
  const url = $('Webhook Recipe URL').first().json.body?.url || $('Webhook Recipe URL').first().json.url || '';

  // Extract title
  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  let title = titleMatch ? titleMatch[1].trim() : 'Untitled Recipe';
  title = title.split(' - ')[0].split(' | ')[0].trim();

  // Try to find JSON-LD recipe schema
  const schemaMatch = html.match(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi);
  let ingredients = [];
  let instructions = [];
  let prepTime = '';
  let cookTime = '';
  let servings = '';
  let category = '';
  let description = '';

  if (schemaMatch) {
    for (const match of schemaMatch) {
      try {
        const jsonStr = match.replace(/<\/?script[^>]*>/gi, '');
        const schema = JSON.parse(jsonStr);
        const recipe = schema['@type'] === 'Recipe' ? schema
          : (Array.isArray(schema['@graph']) ? schema['@graph'].find(s => s['@type'] === 'Recipe') : null);
        if (recipe) {
          title = recipe.name || title;
          ingredients = recipe.recipeIngredient || [];
          instructions = (recipe.recipeInstructions || []).map(i =>
            typeof i === 'string' ? i : i.text || i.name || ''
          );
          prepTime = recipe.prepTime || '';
          cookTime = recipe.cookTime || '';
          servings = recipe.recipeYield ? String(recipe.recipeYield) : '';
          category = recipe.recipeCategory || '';
          description = recipe.description || '';
          break;
        }
      } catch (e) { /* skip invalid JSON */ }
    }
  }

  return {
    json: {
      title,
      url,
      description: description.substring(0, 500),
      ingredients: ingredients.join('\n'),
      instructions: instructions.map((s, i) => `${i + 1}. ${s}`).join('\n'),
      prepTime,
      cookTime,
      servings,
      category
    }
  };
});

